; engine -- the shared player for sound tests 2-5 (the code sweep, test 1, has its own).
;
; A test program is engine.asm + banner + engine_blob.asm + <test>_seq.asm, generated by
; tools/audio/soundtests.py. The sequence file defines N_PHASES, DMA_OFF_AFTER and
; phase_table, one record per phase:
;   +0 channels  +4 period (us per frame)  +8 slot that plays  +12 screen mode (-1 = keep)
;   +16 code held in the other slots  +20 offset of the segment list from blob_start
;   +24 8 stereo positions (-127..127)                                  = 56 bytes
; and a word 0 after the last.
;
; For each phase the foreground changes mode if asked (skipping modes the monitor can't
; show), configures the sound system, sets the stereo positions, and hands the segment
; list to the fill routine through a pending flag, so the interrupt never sees half an
; update. Then it waits for the routine to reach the end of the list.
;
; Run from the F12 command line or outside the desktop. Escape aborts; either way the
; sound system and the screen mode are put back.

	.equ	OS_WriteC,		0x00
	.equ	OS_WriteS,		0x01
	.equ	OS_Write0,		0x02
	.equ	OS_Exit,		0x11
	.equ	OS_GetEnv,		0x10
	.equ	XOS_Byte,		0x20006
	.equ	XOS_Module,		0x2001E
	.equ	XOS_ReadEscapeState,	0x2002C
	.equ	XOS_CheckModeValid,	0x2003F
	.equ	XOS_ReadMonotonicTime,	0x20042
	.equ	XOS_ConvertCardinal4,	0x200D8
	.equ	XSound_Configure,	0x60140
	.equ	XSound_Enable,		0x60141
	.equ	XSound_Stereo,		0x60142

	.equ	BLK_FILL,	0
	.equ	BLK_OVERRUN,	4
	.equ	BLK_LINLOG,	8
	.equ	BLK_LOGSCALE,	12
	.equ	ST_REGS,	16		; R0-R7 of the fill loop: record, left, phase/index,
						; code, A/table, B/length, half, type
	.equ	ST_DONE,	48
	.equ	ST_INDEX,	52
	.equ	ST_SLOT,	56
	.equ	ST_BG,		60		; background code, in all four bytes
	.equ	ST_PEND,	64
	.equ	ST_PSEQ,	68
	.equ	PH_SIZE,	56

	.org	0x8000

start:
	SWI	OS_GetEnv
	MOV	R13,R1
	LDR	R0,addr_banner
	SWI	OS_Write0

	MOV	R0,#6
	LDR	R3,blob_len
	SWI	XOS_Module
	BVS	fail
	MOV	R10,R2
	LDR	R0,addr_blob_start
	LDR	R1,blob_len
copy:	LDR	R3,[R0],#4
	STR	R3,[R2],#4
	SUBS	R1,R1,#4
	BGT	copy
	ADD	R0,R10,#fill - blob_start
	STR	R0,[R10,#BLK_FILL]
	LDR	R0,overrun_offset
	ADD	R0,R10,R0
	STR	R0,[R10,#BLK_OVERRUN]

	MOV	R0,#0
	MOV	R1,#0
	MOV	R2,#0
	MOV	R3,#0
	MOV	R4,#0
	SWI	XSound_Configure
	BVS	fail_free
	ADR	R5,old_config
	STMIA	R5,{R0-R4}
	LDR	R0,[R3,#8]
	STR	R0,[R10,#BLK_LINLOG]
	LDR	R0,[R3,#12]
	STR	R0,[R10,#BLK_LOGSCALE]
	MOV	R0,#0
	SWI	XSound_Enable
	STR	R0,old_enable
	ADR	R5,old_stereo
	MOV	R0,#1
read_st:
	MVN	R1,#127
	SWI	XSound_Stereo
	STR	R1,[R5],#4
	ADD	R0,R0,#1
	CMP	R0,#8
	BLE	read_st
	MOV	R0,#135				; read the screen mode
	SWI	XOS_Byte
	STR	R2,old_mode
	MOV	R11,#0				; set once we change mode

	LDR	R8,addr_phase_table
	MOV	R7,#0
phase_loop:
	LDR	R0,[R8]
	CMP	R0,#0
	BEQ	all_done
	ADD	R7,R7,#1
	LDR	R0,[R8,#12]
	CMN	R0,#1
	BEQ	keep_mode
	SWI	XOS_CheckModeValid
	BCS	skip_phase
	MOV	R6,R0
	MOV	R0,#22
	SWI	OS_WriteC
	MOV	R0,R6
	SWI	OS_WriteC
	MOV	R11,#1
keep_mode:
	LDRB	R0,[R8,#16]
	ORR	R0,R0,R0,LSL #8
	ORR	R0,R0,R0,LSL #16
	STR	R0,[R10,#ST_BG]
	LDR	R0,[R8,#8]
	STR	R0,[R10,#ST_SLOT]
	LDR	R0,[R8,#0]
	MOV	R1,#0
	LDR	R2,[R8,#4]
	MOV	R3,R10
	MOV	R4,#0
	SWI	XSound_Configure
	ADD	R5,R8,#24
	MOV	R0,#1
set_st:	LDR	R1,[R5],#4
	SWI	XSound_Stereo
	ADD	R0,R0,#1
	CMP	R0,#8
	BLE	set_st
	MOV	R0,#2
	SWI	XSound_Enable

	LDR	R0,[R8,#20]
	ADD	R0,R10,R0
	STR	R0,[R10,#ST_PSEQ]
	MOV	R0,#1
	STR	R0,[R10,#ST_PEND]
wait_p:	SWI	XOS_ReadEscapeState
	BCS	aborted
	LDR	R0,[R10,#ST_PEND]
	CMP	R0,#0
	BNE	wait_p

	MVN	R9,#0
wait_d:	SWI	XOS_ReadEscapeState
	BCS	aborted
	LDR	R0,[R10,#ST_DONE]
	CMP	R0,#0
	BNE	next_phase
	LDR	R0,[R10,#ST_INDEX]
	CMP	R0,R9
	BEQ	wait_d
	MOV	R9,R0
	SWI	OS_WriteS
	.byte	13
	.ascii	"phase "
	.byte	0
	.p2align 2
	MOV	R0,R7
	BL	print_number
	SWI	OS_WriteS
	.ascii	" of "
	.byte	0
	.p2align 2
	LDR	R0,n_phases
	BL	print_number
	SWI	OS_WriteS
	.ascii	", segment "
	.byte	0
	.p2align 2
	MOV	R0,R9
	BL	print_number
	SWI	OS_WriteS
	.ascii	"   "
	.byte	0
	.p2align 2
	B	wait_d

next_phase:
	ADD	R8,R8,#PH_SIZE
	B	phase_loop

skip_phase:
	SWI	OS_WriteS
	.byte	13,10
	.ascii	"Screen mode not available on this monitor; skipping phase "
	.byte	0
	.p2align 2
	MOV	R0,R7
	BL	print_number
	SWI	OS_WriteS
	.byte	13,10,0
	.p2align 2
	B	next_phase

all_done:
	LDR	R0,dma_off_after
	CMP	R0,#0
	BEQ	off_done
	MOV	R0,#1				; 5 s with sound DMA off
	SWI	XSound_Enable
	SWI	XOS_ReadMonotonicTime
	ADD	R6,R0,#500
off_wait:
	SWI	XOS_ReadEscapeState
	BCS	aborted
	SWI	XOS_ReadMonotonicTime
	CMP	R0,R6
	BLT	off_wait
off_done:
	BL	restore
	SWI	OS_WriteS
	.byte	13,10
	.ascii	"Done; sound system restored."
	.byte	13,10,0
	.p2align 2
	SWI	OS_Exit

aborted:
	MOV	R0,#124
	SWI	XOS_Byte
	BL	restore
	SWI	OS_WriteS
	.byte	13,10
	.ascii	"Aborted; sound system restored."
	.byte	13,10,0
	.p2align 2
	SWI	OS_Exit

restore:
	STMFD	R13!,{R14}
	ADR	R5,old_config
	LDMIA	R5,{R0-R4}
	MOV	R0,#1
	MOV	R4,#0
	SWI	XSound_Configure
	LDR	R0,old_config
	MOV	R1,#0
	MOV	R2,#0
	MOV	R3,#0
	MOV	R4,#0
	SWI	XSound_Configure
	ADR	R5,old_stereo
	MOV	R0,#1
rest_st:
	LDR	R1,[R5],#4
	SWI	XSound_Stereo
	ADD	R0,R0,#1
	CMP	R0,#8
	BLE	rest_st
	LDR	R0,old_enable
	SWI	XSound_Enable
	MOV	R0,#7
	MOV	R2,R10
	SWI	XOS_Module
	CMP	R11,#0
	BEQ	rest_done
	MOV	R0,#22
	SWI	OS_WriteC
	LDR	R0,old_mode
	SWI	OS_WriteC
rest_done:
	LDMFD	R13!,{PC}

fail_free:
	MOV	R0,#7
	MOV	R2,R10
	SWI	XOS_Module
fail:	SWI	OS_WriteS
	.ascii	"Could not set up the sound system."
	.byte	13,10,0
	.p2align 2
	SWI	OS_Exit

print_number:
	STMFD	R13!,{R0-R2,R14}
	ADR	R1,numbuf
	MOV	R2,#16
	SWI	XOS_ConvertCardinal4
	SWI	OS_Write0
	LDMFD	R13!,{R0-R2,PC}

blob_len:	.long	blob_end - blob_start
overrun_offset:	.long	overrun - blob_start
addr_banner:	.long	banner
addr_blob_start:	.long	blob_start
addr_phase_table:	.long	phase_table
dma_off_after:	.long	DMA_OFF_AFTER
n_phases:	.long	N_PHASES
old_enable:	.long	0
old_mode:	.long	0
old_config:	.skip	20
old_stereo:	.skip	32
numbuf:		.skip	16
